#!/bin/bash
set -e
cd ~/localloop

echo "🌿 Local Loop — deploying round 3 (email notifications)..."

decode_b64() {
  if base64 --version 2>&1 | grep -q GNU; then
    echo "$1" | base64 --decode
  else
    echo "$1" | base64 -d
  fi
}

echo "📝 Writing email API route..."
mkdir -p "app/api/send-approval-email"
decode_b64 "" > "app/api/send-approval-email/route.ts"
git add "app/api/send-approval-email/route.ts"
git commit -m "Add approval email API route via Resend"
git push
echo "✓ API route committed"

echo "📝 Updating admin page with email trigger..."
decode_b64 "" > app/admin/page.tsx
git add app/admin/page.tsx
git commit -m "Trigger approval/rejection email from admin dashboard"
git push
echo "✓ admin/page.tsx updated and committed"

echo ""
echo "🎉 Round 3 complete! Email notifications wired up."
echo "   Don't forget to add RESEND_API_KEY and SUPABASE_SERVICE_ROLE_KEY in Vercel."
